/* Severance — Lumon terminal teal, pale cyan data, sterile corporate calm */
.theme-severance {
  --bg: oklch(0.257 0.055 240.9);
  --surface: oklch(0.304 0.060 236.2);
  --surface-2: oklch(0.354 0.067 233.5);
  --fg: oklch(0.849 0.044 207.3);
  --fg-muted: oklch(0.615 0.053 215.9);
  --accent: oklch(0.787 0.074 202.3);
  --accent-fg: oklch(0.257 0.055 240.9);
  --accent-2: oklch(0.914 0.027 205.4);
  --line: oklch(0.75 0.06 210 / 30%);
  --success: oklch(0.787 0.074 202.3);
  --warning: oklch(0.820 0.092 92.4);
  --danger: oklch(0.692 0.113 20.4);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 0.5rem;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 14px color-mix(in oklab, var(--accent) 40%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "IBM Plex Sans", sans-serif;
  --font-body: "IBM Plex Sans", sans-serif;
  --font-mono: "IBM Plex Mono", monospace;
  --tracking-display: 0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.18em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-severance h1,
.theme-severance h2,
.theme-severance h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-severance { background-image: radial-gradient(ellipse at 50% -20%, oklch(0.45 0.08 220 / 40%), transparent 55%); }
.theme-severance h1 { font-weight: 500; color: #cfe8eb; }
.theme-severance h2::before { content: "◇ "; color: var(--accent); font-size: 0.7em; vertical-align: middle; }
.theme-severance .label-caps { letter-spacing: 0.24em; }
.theme-severance table, .theme-severance input { font-family: var(--font-mono); }

/* alt-mode — the severed floor: sterile white corridors, Lumon green trim */
.theme-severance.alt-mode {
  --bg: oklch(0.965 0.008 200.0);
  --surface: oklch(0.990 0.004 200.0);
  --surface-2: oklch(0.930 0.014 202.0);
  --fg: oklch(0.300 0.055 235.0);
  --fg-muted: oklch(0.520 0.050 220.0);
  --accent: oklch(0.500 0.085 200.0);
  --accent-fg: oklch(0.980 0.005 200.0);
  --accent-2: oklch(0.420 0.070 235.0);
  --line: oklch(0.50 0.06 210 / 30%);
  --success: oklch(0.520 0.090 165.0);
  --warning: oklch(0.640 0.120 85.0);
  --danger: oklch(0.540 0.150 22.0);
  --shadow-1: 0 1px 3px oklch(0.4 0.04 220 / 12%);
  --shadow-2: 0 8px 24px oklch(0.4 0.04 220 / 14%);
  --shadow-3: 0 24px 56px oklch(0.4 0.04 220 / 18%);
  --glow: 0 0 12px color-mix(in oklab, var(--accent) 25%, transparent);
  background-image: radial-gradient(ellipse at 50% -20%, oklch(0.90 0.02 200 / 70%), transparent 55%);
}
.theme-severance.alt-mode h1 { color: oklch(0.28 0.06 235); }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
